import { Component, Input, OnInit } from '@angular/core';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { DownloadFuncType, IDownloadInput } from '../interfaces/excel-io.interface';

export interface IExportWizardModalInput {
    columns: Array<{
        name: string;
        inputType: 'text' | 'tel' | 'email' | 'date' | 'number' | 'checkbox' | 'file'; // On purpose do not use the Type from ngx reactive table, to get ride of this dependency
        prop: string;
    }>;
    downloadAsync?: DownloadFuncType;
}

@Component({
    selector: 'polp-export-wizard-modal',
    templateUrl: './export-wizard-modal.component.html',
    styleUrls: ['./export-wizard-modal.component.css'],
    standalone: false
})
export class ExportWizardModalComponent implements OnInit {

    @Input() columns: Array<{
        name: string;
        inputType: 'text' | 'tel' | 'email' | 'date' | 'number' | 'checkbox' | 'file';
        prop: string;
    }> = [];
    @Input() downloadAsync: DownloadFuncType = (_: IDownloadInput) => {
        return new Promise(function(resolve, reject) {
            resolve({
                totalCount: 0,
                items: []
            });
        });
    };

    title = 'Export wizard';

    constructor(
        public readonly bsModalRef: BsModalRef,
        protected readonly bsModalService: BsModalService
    ) {
    }

    ngOnInit(): void {
    }

    close() {
        this.bsModalRef.hide();
    }
}
