import { Component, EventEmitter, Input, OnDestroy, OnInit, Output, TemplateRef, ViewChild } from '@angular/core';
import { faArrowCircleUp, faArrowUp, faCheck, faHourglass, faTimes } from '@fortawesome/free-solid-svg-icons';
import { SearchBoxWidgetComponent } from '@polpware/bs-components';
import { NgxNotyImpl } from '@polpware/ngx-noty';
import { getInputType, IRowDataType, ITableColumnSpec, ITableDataChangeEvent, NgxDatatableLocalData, sliceArray, supportOperationsDecorator } from '@polpware/ngx-reactive-table';
import { DatatableComponent } from '@swimlane/ngx-datatable';
import { LogMessage } from 'ngx-log-monitor';
import { ReplaySubject } from 'rxjs';

interface IPubRowType extends IRowDataType {
    _state: 'waiting' | 'working' | 'success' | 'failure';
}

@supportOperationsDecorator
@Component({
    selector: 'polp-data-publication',
    templateUrl: './data-publication.component.html',
    styleUrls: ['./data-publication.component.css'],
    standalone: false
})
export class DataPublicationComponent extends NgxDatatableLocalData<IPubRowType>
    implements OnInit, OnDestroy {

    @Input() initData: IRowDataType[] = [];
    @Input() columnNames: { [key: string]: string } = {};
    @Input() uploadAsync: (data: Array<IRowDataType>) => Promise<{
        failures: Array<IRowDataType>;
        errors: Array<string>;
    }> = (data: Array<IRowDataType>) => {
        return new Promise(function(resolve, reject) {
            resolve({
                failures: [],
                errors: []
            });
        });
    };
    @Output() onImport = new EventEmitter<void>();
    @Output() afterImport = new EventEmitter<{ success: number; failure: number }>();

    faCheck = faCheck;
    faTimes = faTimes;
    faHourglass = faHourglass;
    faArrowCircleUp = faArrowCircleUp;
    faArrowUp = faArrowUp;

    // Used to keep the original rows 
    originalRows: IPubRowType[] = [];

    showLogs = false;
    logStream = new ReplaySubject<LogMessage>();

    @ViewChild('searchBox4DataPub', { static: true }) searchBox: SearchBoxWidgetComponent;

    @ViewChild('datatable', { static: true }) datatable: DatatableComponent;

    @ViewChild("stateHeader", { static: true }) stateHeaderTmpl: TemplateRef<any>;
    @ViewChild("stateCell ", { static: true }) stateCellTmpl: TemplateRef<any>;
    @ViewChild("titleCell ", { static: true }) titleCellTmpl: TemplateRef<any>;
    @ViewChild("inputCell ", { static: true }) inputCellTmpl: TemplateRef<any>;

    private _importStat: { success: number; failure: number } = { success: 0, failure: 0 };

    constructor(public readonly noty: NgxNotyImpl) {
        super();
    }

    get anyKeyword() {
        return this.searchBox ? this.searchBox.effectiveKeyword : '';
    }

    ngOnInit(): void {
        this.settings = Object.assign({}, this.settings, { pageSize: 10, canCreate: true, canDelete: true, canUpdate: true });
        this.pageSize = this.settings.pageSize;
        this.buildColumns();
    }

    ngOnDestroy(): void {
    }

    // Starts a new round of search
    //
    // This operation causes new network request.
    public kickOffSearch() {
        const k = this.searchBox.effectiveKeyword;
        if (k) {
            this.rows = this.originalRows.filter(elem => {
                for (let prop in elem) {
                    if (prop != 'id' && elem.hasOwnProperty(prop)) {
                        const v = elem[prop];
                        if (v) {
                            const w: string = v.toString().toLowerCase();
                            if (w.includes(k)) {
                                return true;
                            }
                        }
                    }
                }
                return false;
            });
        } else {
            this.rows = this.originalRows;
        }
    }

    buildColumns() {

        if (!this.initData || this.initData.length <= 0) {
            return;
        }

        const columns: Array<ITableColumnSpec> = [];
        columns.push({
            width: 50,
            sortable: false,
            canAutoResize: false,
            draggable: false,
            resizeable: false,
            headerCheckboxable: true,
            checkboxable: true
        });
        columns.push({
            name: 'State',
            prop: '_state',
            width: 80,
            sortable: false,
            canAutoResize: false,
            draggable: false,
            resizeable: false,
            headerTemplate: this.stateHeaderTmpl,
            cellTemplate: this.stateCellTmpl
        });

        const firstRow = this.initData[0];
        for (let prop in this.columnNames) {
            const c: ITableColumnSpec = {
                name: this.columnNames[prop],
                prop: prop,
                sortable: true,
                minWidth: 150,
                editable: true,
                inputType: getInputType(firstRow[prop]),
                headerTemplate: this.titleCellTmpl,
                cellTemplate: this.inputCellTmpl
            };
            columns.push(c);
        }

        this.columns = columns;
        this.originalRows = this.initData.map(a => {
            return Object.assign({ _state: 'waiting' }, a) as IPubRowType;
        });
        this.rows = this.originalRows;
        this.searchBox && this.searchBox.searchControl && this.searchBox.resetKeyword(false);
    }

    // Override
    publish(event: ITableDataChangeEvent) {
        if (event.op == 'create') {
            // Add 
            const data = event.data as IPubRowType;
            this.originalRows.push(data);
        } else if (event.op == 'update') {
            // Add or edit
            // We do not need to preserve value semantics;
            // therefore, we can do in-place editing.
            const data = event.data as IPubRowType;
            const index = this.originalRows.findIndex(a => a.id == data.id);
            if (index != -1) {
                this.originalRows.splice(index, 1, data);
            }
        } else if (event.op == 'delete') {
            // Remove
            const data = event.data as IPubRowType[];
            this.originalRows = this.originalRows.filter(a => {
                return !data.some(b => b.id == a.id);
            });
        }
    }

    async uploadSelectedAsync() {
        // Emit a message 
        this.onImport.emit();
        const todo = this.selected.filter(a => a._state != 'success');
        this.logStream.next({
            type: 'INFO',
            message: `Start to import the selected records (${todo.length})`
        });
        const noError = await this.invokeUploadAsync(todo);

        if (noError) {
            this.logStream.next({
                type: 'SUCCESS',
                message: 'Successfully uploaded the selected records'
            });
        }
        this.showLogs = true;
    }

    // This will work for filter set or all.
    async uploadAllAsync() {
        // Emit a message 
        this.onImport.emit();
        // Page by page
        const internalRows = this.datatable._internalRows;
        const totalPages = Math.ceil(internalRows.length / this.pageSize);
        let noError = true;
        // Disable sorting but preserve the current order
        this.datatable.sorts = [];
        this.datatable.rows = internalRows;

        this.logStream.next({
            type: 'INFO',
            message: `Start to import all records`
        });

        for (let pIndex = 0; (noError && pIndex < totalPages); pIndex++) {

            this.logStream.next({
                type: 'INFO',
                message: `Import ${pIndex + 1} page`
            });

            this.datatable._offset = pIndex;
            // One page 
            let todo = sliceArray(internalRows, pIndex * this.pageSize, (pIndex + 1) * this.pageSize);
            todo = todo.filter(a => a._state != 'success');
            noError = await this.invokeUploadAsync(todo);
        }

        if (noError) {
            this.logStream.next({
                type: 'SUCCESS',
                message: 'Successfully uploaded all records'
            });
        }

        this.showLogs = true;
    }

    // We expect that the underlying upload method is working in a transactional way.
    // I.e., either all the data is uploaded or none of them is uploaded.
    async invokeUploadAsync(data: Array<IPubRowType>) {
        let noError = true;
        try {
            data.forEach(elem => elem._state = 'working');
            // Trigger value semantics
            this.rows = [...this.rows];
            // Update state 
            // Start with the first page and then move on
            const ret = await this.uploadAsync(data);
            // todo: Error handling
            data.forEach(elem => elem._state = 'success');
            ret.failures.forEach(p => {
                const q = data.find(x => x.id == p.id);
                q && (q._state = 'failure');
            });
            // Force to change             
            this.rows = [...this.rows];

            this.logStream.next({
                type: 'SUCCESS',
                message: `Imported ${data.length - ret.failures.length} records`
            });

            if (ret.failures && ret.failures.length) {
                noError = false;
                this.logStream.next({
                    type: 'ERR',
                    message: `Failed to import ${ret.failures.length} records`
                });
            }

            if (ret.errors && ret.errors.length) {
                ret.errors.forEach(e => {
                    this.logStream.next({
                        type: 'ERR',
                        message: `Error: ${e}`
                    });
                });
            }

            this._importStat.success += (data.length - ret.failures.length);
            this._importStat.failure += ret.failures.length;

            this.afterImport.emit(this._importStat);

        } catch (e) {
            // In place editing
            data.forEach(elem => elem._state = 'failure');
            // Force to change 
            this.rows = [...this.rows];
            noError = false;
        }
        return noError;
    }
}
