import { Component, Input, OnChanges, OnInit, SimpleChanges, TemplateRef, ViewChild } from '@angular/core';
import { getInputType, IRowDataType, ITableColumnSpec, NgxDatatablePoweredBase } from '@polpware/ngx-reactive-table';
import { DatatableComponent } from '@swimlane/ngx-datatable';

@Component({
    selector: 'polp-data-preview',
    templateUrl: './data-preview.component.html',
    styleUrls: ['./data-preview.component.css'],
    standalone: false
})
export class DataPreviewComponent extends NgxDatatablePoweredBase<IRowDataType>
    implements OnInit, OnChanges {

    @Input() initData: IRowDataType[] = [];
    @Input() columnNames: { [key: string]: string } = {};

    @ViewChild('datatable', { static: true }) datatable: DatatableComponent;

    @ViewChild("titleCell ", { static: true }) titleCellTmpl: TemplateRef<any>;

    constructor() {
        super();
    }

    ngOnInit(): void {
        this.settings = Object.assign({}, this.settings, { pageSize: 10, editable: true });
        this.pageSize = this.settings.pageSize;

        this.buildColumns();
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes.initData && !changes.initData.firstChange && changes.initData.currentValue) {
            this.buildColumns();
        }
    }

    buildColumns() {

        if (!this.initData || this.initData.length <= 0) {
            return;
        }

        const columns: Array<ITableColumnSpec> = [];
        const firstRow = this.initData[0];
        for (let prop in this.columnNames) {
            const c: ITableColumnSpec = {
                name: this.columnNames[prop],
                prop: prop,
                sortable: true,
                minWidth: 150,
                editable: true,
                inputType: getInputType(firstRow[prop]),
                headerTemplate: this.titleCellTmpl
            };
            columns.push(c);
        }

        this.columns = columns;
        this.rows = this.initData;
    }
}
