import { Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges, TemplateRef, ViewChild } from '@angular/core';
import { faCheck, faEdit, faExclamationTriangle, faPlus, faSearch, faTimes, faTrash, faUndo } from '@fortawesome/free-solid-svg-icons';
import { SearchBoxWidgetComponent } from '@polpware/bs-components';
import { NgxNotyImpl } from '@polpware/ngx-noty';
import { getInputType, IRowDataType, ITableColumnSpec, ITableDataChangeEvent, NgxDatatableLocalData, supportOperationsDecorator } from '@polpware/ngx-reactive-table';
import { DatatableComponent } from '@swimlane/ngx-datatable';
import { LogMessage } from 'ngx-log-monitor';
import { ReplaySubject } from 'rxjs';

@supportOperationsDecorator
@Component({
    selector: 'polp-data-processor',
    templateUrl: './data-processor.component.html',
    styleUrls: ['./data-processor.component.css'],
    standalone: false
})
export class DataProcessorComponent extends NgxDatatableLocalData<IRowDataType>
    implements OnInit, OnChanges, OnDestroy {

    @Input() initData: IRowDataType[] = [];
    @Input() columnNames: { [key: string]: string } = {};
    @Output() dataChange = new EventEmitter<ITableDataChangeEvent>();
    @Output() onReset = new EventEmitter<void>();

    @ViewChild('searchBox', { static: true }) searchBox: SearchBoxWidgetComponent;
    @ViewChild('datatable', { static: true }) datatable: DatatableComponent;

    @ViewChild("editActionHeader", { static: true }) editActionHeaderTmpl: TemplateRef<any>;
    @ViewChild("editActionCell ", { static: true }) editActionCellTmpl: TemplateRef<any>;
    @ViewChild("inputCell ", { static: true }) inputCellTmpl: TemplateRef<any>;

    // Support operations over data
    faEdit = faEdit;
    faTrash = faTrash;
    faCheck = faCheck;
    faTimes = faTimes;
    faPlus = faPlus;
    faUndo = faUndo;
    faExclamationTriangle = faExclamationTriangle;
    faSearch = faSearch;

    isConfirmReset = false;
    // Used to keep the original rows 
    originalRows: IRowDataType[] = [];

    showLogs = false;
    logStream = new ReplaySubject<LogMessage>();

    constructor(public readonly noty: NgxNotyImpl) {
        super();
    }

    get editable() {
        return this.settings ? (this.settings.canCreate || this.settings.canDelete || this.settings.canUpdate) : false;
    }

    ngOnInit(): void {
        this.settings = Object.assign({}, this.settings, { pageSize: 10, canCreate: true, canUpdate: true, canDelete: true });
        this.pageSize = this.settings.pageSize;

        this.buildColumns();
    }

    ngOnChanges(changes: SimpleChanges) {
        if (changes.initData && !changes.initData.firstChange && changes.initData.currentValue) {
            this.buildColumns();
        }
    }

    ngOnDestroy(): void {
    }

    // Starts a new round of search
    //
    // This operation causes new network request.
    public kickOffSearch() {
        const k = this.searchBox.effectiveKeyword;
        if (k) {
            this.rows = this.originalRows.filter(elem => {
                for (let prop in elem) {
                    if (prop != 'id' && elem.hasOwnProperty(prop)) {
                        const v = elem[prop];
                        if (v) {
                            const w: string = v.toString().toLowerCase();
                            if (w.includes(k)) {
                                return true;
                            }
                        }
                    }
                }
                return false;
            });
        } else {
            this.rows = this.originalRows;
        }
    }


    buildColumns() {

        if (!this.initData || this.initData.length <= 0) {
            return;
        }

        const columns: Array<ITableColumnSpec> = [];
        columns.push({
            width: 50,
            sortable: false,
            canAutoResize: false,
            draggable: false,
            resizeable: false,
            headerCheckboxable: true,
            checkboxable: true
        });
        columns.push({
            name: 'Actions',
            width: 120,
            sortable: false,
            canAutoResize: false,
            draggable: false,
            resizeable: false,
            headerTemplate: this.editActionHeaderTmpl,
            cellTemplate: this.editActionCellTmpl
        });

        const firstRow = this.initData[0];
        for (let prop in this.columnNames) {
            const c: ITableColumnSpec = {
                name: this.columnNames[prop],
                prop: prop,
                sortable: true,
                minWidth: 150,
                editable: true,
                inputType: getInputType(firstRow[prop]),
                cellTemplate: this.inputCellTmpl
            };
            columns.push(c);
        }

        this.columns = columns;
        this.originalRows = [...this.initData];
        this.rows = [...this.initData];
        this.searchBox && this.searchBox.searchControl && this.searchBox.resetKeyword(false);
    }

    reset() {
        this.onReset.emit();

        this.logStream.next({
            type: 'INFO',
            message: `reset record(s)`
        });
        this.showLogs = true;
    }

    // Override
    publish(event: ITableDataChangeEvent) {
        if (event.op == 'create') {
            // Add 
            const data = event.data as IRowDataType;
            this.originalRows.push(data);

            this.logStream.next({
                type: 'INFO',
                message: `Created a new record`
            });
            this.showLogs = true;

        } else if (event.op == 'update') {
            // Add or edit
            // We do not need to preserve value semantics;
            // therefore, we can do in-place editing.
            const data = event.data as IRowDataType;
            const index = this.originalRows.findIndex(a => a.id == data.id);
            if (index != -1) {
                this.originalRows.splice(index, 1, data);
                this.logStream.next({
                    type: 'INFO',
                    message: `Updated a record`
                });
                this.showLogs = true;
            }
        } else if (event.op == 'delete') {
            // Remove
            const data = event.data as IRowDataType[];
            this.originalRows = this.originalRows.filter(a => {
                return !data.some(b => b.id == a.id);
            });

            this.logStream.next({
                type: 'INFO',
                message: `removed ${data.length} record(s)`
            });
            this.showLogs = true;
        }
        // Notify client 
        this.dataChange.emit(Object.assign({}, event, { rows: this.originalRows }));
    }
}
