import { Component, Input, OnInit, ViewChild } from '@angular/core';
import { IRowDataType } from '@polpware/ngx-reactive-table';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { ImportDataWizardComponent } from '../import-data-wizard/import-data-wizard.component';

export interface IImportWizardModalInput {
    file: File;
    columns: Array<{
        id: string;
        label: string;
        required: boolean;
    }>;
    uploadAsync?: (data: Array<IRowDataType>) => Promise<{
        failures: Array<IRowDataType>;
        errors: Array<string>;
    }>;
    successCallback?: () => any;
}

@Component({
    selector: 'polp-import-wizard-modal',
    templateUrl: './import-wizard-modal.component.html',
    styleUrls: ['./import-wizard-modal.component.css'],
    standalone: false
})
export class ImportWizardModalComponent implements OnInit {

    @Input() file: File;
    @Input() columns: Array<{
        id: string;
        label: string;
        required: boolean;
    }> = [];
    @Input() uploadAsync: (data: Array<IRowDataType>) => Promise<{
        failures: Array<IRowDataType>;
        errors: Array<string>;
    }> = (data: Array<IRowDataType>) => {
        return new Promise(function(resolve, reject) {
            resolve({
                failures: [],
                errors: []
            });
        });
    };
    @Input() successCallback: () => any = null;

    @ViewChild('importDataWizard', { static: true }) importDataWizard: ImportDataWizardComponent;

    title = 'Import wizard';

    constructor(
        public readonly bsModalRef: BsModalRef,
        protected readonly bsModalService: BsModalService
    ) {
    }

    ngOnInit(): void {
    }

    close() {

        if (this.importDataWizard.importStat.success) {
            this.successCallback && this.successCallback();
        }

        this.bsModalRef.hide();
    }

}
